@ SIO link session lightweight teardown function. Called by pack/campaign scene state machine
@ on SIO link reset. Symmetric counterpart to setup_sio_link_session (0x080edd90).
@ Steps: (1) clear IME (disable interrupts);
@ (2) ldrh IE, mask off bit5 (serial interrupt bit) via ands 0x0000ffdf, strh back;
@ (3) strh 1,[IME] restore interrupt enable;
@ (4) str 0,[0x03000000+0x18] clear SIO interrupt callback ptr;
@ (5) bl reinit_sio_link_with_timer3 to reset SIO link and Timer3.
@ setup_sio_link_session sets IE serial bit and registers callback;
@ teardown_sio_link_session clears IE serial bit and deregisters callback.
@ 
@ Constants:
@ - IE_SERIAL_MASK_OFF = 0x0000ffdf (DAT_080ede54, = ~0x20, clears serial bit)
@ - IWRAM_SIO_BASE = 0x03000000 (DAT_080ede58)
@ - SIO_CALLBACK_FIELD = +0x18
teardown_sio_link_session:
    push {lr}                                @ 080ede28 00b5
    ldr r3, PTR_IME_080ede4c                 @ 080ede2a 084b
    movs r0,#0x0    @ 080ede2c 0020
    strh r0,[r3,#0x0]                        @ 080ede2e 1880
    ldr r2, PTR_IE_080ede50                  @ 080ede30 074a
    ldrh r1,[r2,#0x0]                        @ 080ede32 1188
    ldr r0, DAT_080ede54                     @ 080ede34 0748
    ands r0,r1    @ 080ede36 0840
    strh r0,[r2,#0x0]                        @ 080ede38 1080
    movs r0,#0x1    @ 080ede3a 0120
    strh r0,[r3,#0x0]                        @ 080ede3c 1880
    ldr r1, DAT_080ede58                     @ 080ede3e 0649
    movs r0,#0x0    @ 080ede40 0020
    str r0,[r1,#0x18]                        @ 080ede42 8861
    bl reinit_sio_link_with_timer3           @ 080ede44 01f09afc
    pop {r0}                                 @ 080ede48 01bc
    bx r0                                    @ 080ede4a 0047
PTR_IME_080ede4c:
    .word  IME                            @ 080ede4c 08020004
PTR_IE_080ede50:
    .word  IE                             @ 080ede50 00020004
DAT_080ede54:
    .word  0x0000ffdf                     @ 080ede54 dfff0000
DAT_080ede58:
    .word  0x03000000                     @ 080ede58 00000003

@ Initialize BG2 and BG3 affine transform matrices to identity and clear scroll offsets. For BG2: writes [BG2X+0]=0, [BG2X+4]=0 (BG2X/BG2Y scroll clear); writes [BG2X-8]=0x100 (BG2PA=1.0), [BG2X-6]=0 (BG2PB), [BG2X-4]=0 (BG2PC), [BG2X-2]=0x100 (BG2PD=1.0). Applies same 6-write layout for BG3 (base+0x12). Writes BG0CNT=0x4. Leaf function, no push/pop, indeg=6.
@ 
@ Constants:
@ - BG2X = 0x04000028 (PTR_BG2X_080ede9c)
@ - BG2PA=0x04000020, BG2PB=0x04000022, BG2PC=0x04000024, BG2PD=0x04000026
@ - IDENTITY = 0x100 (0x80<<1, 1.0 in 8.8 fixed point)
@ - BG0CNT = 0x04000008, write value = 0x4
reset_affine_bg_matrix_and_scroll:
    ldr r0, PTR_BG2X_080ede9c                @ 080ede5c 0f48
    movs r1,#0x0    @ 080ede5e 0021
    str r1,[r0,#0x0]                         @ 080ede60 0160
    adds r0,#0x4    @ 080ede62 0430
    str r1,[r0,#0x0]                         @ 080ede64 0160
    subs r0,#0xc    @ 080ede66 0c38
    movs r3,#0x80    @ 080ede68 8023
    lsls r3,r3,#0x1    @ 080ede6a 5b00
    adds r2,r3,#0x0    @ 080ede6c 1a1c
    strh r2,[r0,#0x0]                        @ 080ede6e 0280
    adds r0,#0x2    @ 080ede70 0230
    strh r1,[r0,#0x0]                        @ 080ede72 0180
    adds r0,#0x2    @ 080ede74 0230
    strh r1,[r0,#0x0]                        @ 080ede76 0180
    adds r0,#0x2    @ 080ede78 0230
    strh r2,[r0,#0x0]                        @ 080ede7a 0280
    adds r0,#0x12    @ 080ede7c 1230
    str r1,[r0,#0x0]                         @ 080ede7e 0160
    adds r0,#0x4    @ 080ede80 0430
    str r1,[r0,#0x0]                         @ 080ede82 0160
    subs r0,#0xc    @ 080ede84 0c38
    strh r2,[r0,#0x0]                        @ 080ede86 0280
    adds r0,#0x2    @ 080ede88 0230
    strh r1,[r0,#0x0]                        @ 080ede8a 0180
    adds r0,#0x2    @ 080ede8c 0230
    strh r1,[r0,#0x0]                        @ 080ede8e 0180
    adds r0,#0x2    @ 080ede90 0230
    strh r2,[r0,#0x0]                        @ 080ede92 0280
    ldr r1, PTR_BG0CNT_080edea0              @ 080ede94 0249
    movs r0,#0x4    @ 080ede96 0420
    strh r0,[r1,#0x0]                        @ 080ede98 0880
    bx lr                                    @ 080ede9a 7047
PTR_BG2X_080ede9c:
    .word  BG2X                           @ 080ede9c 28000004
PTR_BG0CNT_080edea0:
    .word  BG0CNT                         @ 080edea0 08000004

@ Zero-fill a range of BG VRAM tile rows. r1 high 11 bits (lsrs#0x15) = row_count, low 5 bits (lsrs#0x10 & 0x1f) = x_tile. r2 high 11 bits = fill_count, low 5 bits = tile_width. Computes start address: 0x06000000 (0xc0<<0x13) + x_tile + r0<<11 (row * 0x800 bytes per row). Loops row_count times: calls zero_fill_by_halfword(addr, tile_width), addr += 0x20 (32 bytes per row step).
@ 
@ Constants:
@ - BG_VRAM_BASE = 0x06000000 (0xc0<<0x13)
@ - ROW_STRIDE = 0x20 = 32 bytes (tile row step)
@ - x_tile = r1[4:0], row_count = r1[26:21]
@ - tile_width = r2[4:0], fill_count = r2[26:21]
zero_fill_bg_vram_row_range:
    push {r4,r5,r6,lr}                       @ 080edea4 70b5
    adds r4,r0,#0x0    @ 080edea6 041c
    lsls r1,r1,#0x10    @ 080edea8 0904
    lsls r2,r2,#0x10    @ 080edeaa 1204
    movs r0,#0x1f    @ 080edeac 1f20
    lsrs r3,r1,#0x10    @ 080edeae 0b0c
    ands r3,r0    @ 080edeb0 0340
    lsrs r1,r1,#0x15    @ 080edeb2 490d
    lsrs r6,r2,#0x10    @ 080edeb4 160c
    ands r6,r0    @ 080edeb6 0640
    lsrs r5,r2,#0x15    @ 080edeb8 550d
    cmp r5,#0x0                              @ 080edeba 002d
    beq LAB_080ededc                         @ 080edebc 0ed0
    lsls r2,r1,#0x5    @ 080edebe 4a01
    lsls r1,r4,#0xb    @ 080edec0 e102
    movs r0,#0xc0    @ 080edec2 c020
    lsls r0,r0,#0x13    @ 080edec4 c004
    adds r0,r3,r0    @ 080edec6 1818
    adds r1,r1,r0    @ 080edec8 0918
    adds r4,r2,r1    @ 080edeca 5418
LAB_080edecc:
    adds r0,r4,#0x0    @ 080edecc 201c
    adds r1,r6,#0x0    @ 080edece 311c
    bl zero_fill_by_halfword                 @ 080eded0 06f0d0ff
    adds r4,#0x20    @ 080eded4 2034
    subs r5,#0x1    @ 080eded6 013d
    cmp r5,#0x0                              @ 080eded8 002d
    bne LAB_080edecc                         @ 080ededa f7d1
LAB_080ededc:
    pop {r4,r5,r6}                           @ 080ededc 70bc
    pop {r0}                                 @ 080edede 01bc
    bx r0                                    @ 080edee0 0047
    .zero  0x2

@ Zero-fill a single BG2 tile VRAM row.
@ r0=row_index (u16) [0..31], r1=tile_width (u16) [0..32].
@ Entry: lsls r0,r0,#0x10; lsrs r0,r0,#0xb converts row_index to byte offset (row*0x20).
@ Adds base 0x06004000 (BG2 tile VRAM area) to get target address.
@ Calls zero_fill_by_halfword(target, tile_width) to clear tile_width halfwords.
@ Inner single-row primitive; sibling of zero_fill_bg_vram_row_range (0x080edea4).
@ indeg=0 (grep ".word 0x080edee5" = 0 hits).
@ 
@ Constants:
@ - BG2_VRAM_BASE = 0x06004000 (DWORD_080edefc)
@ - ROW_STRIDE_SHIFT = 0x10-0xb = 0x15 (lsls 0x10 then lsrs 0xb => row*0x20 bytes)
zero_fill_vram_bg2_row:
    push {lr}                                @ 080edee4 00b5
    lsls r0,r0,#0x10    @ 080edee6 0004
    lsls r1,r1,#0x10    @ 080edee8 0904
    lsrs r0,r0,#0xb    @ 080edeea c00a
    ldr r2, DWORD_080edefc                   @ 080edeec 034a
    adds r0,r0,r2    @ 080edeee 8018
    lsrs r1,r1,#0xb    @ 080edef0 c90a
    bl zero_fill_by_halfword                 @ 080edef2 06f0bfff
    pop {r0}                                 @ 080edef6 01bc
    bx r0                                    @ 080edef8 0047
    .zero  0x2
DWORD_080edefc:
    .word  0x06004000                     @ 080edefc 00400006

@ 将一个复合数据结构中的 tile 图像数据和调色板数据分两次通过 copy_bytes_by_halfword 分别上传到 OBJ VRAM (0x06004000+) 和调色板 RAM (0x05000000+). r0=tile_index (用于调色板 RAM 写偏移: tile_index*2 + 0x05000000; u16 截断存入 r4), r1=src_tile_ref (用于 VRAM 写偏移: src_tile_ref*32 + 0x06004000; lsls r1,#16 >> r0,#11 计算), r2=data_struct 指针, [r2+0]=width halfword, r6=r2+width*2+8 为调色板子结构. 被两个 bg/vram/palette 相关 caller 调用, 是将字体/图标资源一次性写入 VRAM 和调色板的工具函数. 返回 [r6] (调色板子结构第一个 halfword).
upload_tile_and_palette_from_struct:
    push {r4,r5,r6,lr}                       @ 080edf00 70b5
    adds r4,r0,#0x0    @ 080edf02 041c
    adds r0,r1,#0x0    @ 080edf04 081c
    adds r5,r2,#0x0    @ 080edf06 151c
    lsls r4,r4,#0x10    @ 080edf08 2404
    lsrs r4,r4,#0x10    @ 080edf0a 240c
    lsls r0,r0,#0x10    @ 080edf0c 0004
    ldrh r2,[r5,#0x0]                        @ 080edf0e 2a88
    lsls r1,r2,#0x1    @ 080edf10 5100
    adds r6,r1,#0x0    @ 080edf12 0e1c
    adds r6,#0x8    @ 080edf14 0836
    adds r6,r5,r6    @ 080edf16 ae19
    adds r1,#0x10    @ 080edf18 1031
    adds r1,r5,r1    @ 080edf1a 6918
    lsrs r0,r0,#0xb    @ 080edf1c c00a
    ldr r3, DAT_080edf48                     @ 080edf1e 0a4b
    adds r0,r0,r3    @ 080edf20 c018
    ldrh r3,[r6,#0x0]                        @ 080edf22 3388
    lsls r2,r3,#0x5    @ 080edf24 5a01
    bl copy_bytes_by_halfword                @ 080edf26 06f0bdff
    lsls r4,r4,#0x1    @ 080edf2a 6400
    movs r0,#0xa0    @ 080edf2c a020
    lsls r0,r0,#0x13    @ 080edf2e c004
    adds r4,r4,r0    @ 080edf30 2418
    adds r1,r5,#0x0    @ 080edf32 291c
    adds r1,#0x8    @ 080edf34 0831
    ldrh r5,[r5,#0x0]                        @ 080edf36 2d88
    lsls r2,r5,#0x1    @ 080edf38 6a00
    adds r0,r4,#0x0    @ 080edf3a 201c
    bl copy_bytes_by_halfword                @ 080edf3c 06f0b2ff
    ldrh r0,[r6,#0x0]                        @ 080edf40 3088
    pop {r4,r5,r6}                           @ 080edf42 70bc
    pop {r1}                                 @ 080edf44 02bc
    bx r1                                    @ 080edf46 0847
DAT_080edf48:
    .word  0x06004000                     @ 080edf48 00400006

