    lsrs r2,r4,#0x1c    @ 080f0762 220f
    lsls r2,r2,#0x1    @ 080f0764 5200
    adds r2,r2,r5    @ 080f0766 5219
    lsrs r1,r4,#0x18    @ 080f0768 210e
